const now = new Date();
const upcoming = [];
const archive = [];
for (const item of items) {
  const record = item.json;
  const edge = new Date(record.event_end_at || record.event_start_at);
  if (edge.getTime() < now.getTime()) {
    archive.push(record);
  } else {
    upcoming.push(record);
  }
}
return [{ json: { generated_at: new Date().toISOString(), upcoming, archive } }];
